<?php
require 'config.php'; auth(); $pdo=db();
$from=$_GET['from']??date('Y-m-01');$to=$_GET['to']??date('Y-m-d');$jenis=$_GET['jenis']??'SEMUA';
if(!preg_match('/^\d{4}-\d{2}-\d{2}$/',$from))$from=date('Y-m-01');if(!preg_match('/^\d{4}-\d{2}-\d{2}$/',$to))$to=date('Y-m-d');if($from>$to)[$from,$to]=[$to,$from];
if(!in_array($jenis,['SEMUA','MASUK','KELUAR'],true))$jenis='SEMUA';
$where="t.tanggal BETWEEN ? AND ?";$params=[$from,$to];if($jenis!=='SEMUA'){$where.=" AND t.jenis=?";$params[]=$jenis;}
if(($_GET['export']??'')==='csv'){
 $s=$pdo->prepare("SELECT t.tanggal,b.kode_barang,b.nama_barang,b.kategori,b.satuan,t.jenis,t.jumlah,t.referensi,t.keterangan,u.name AS petugas FROM transaksi t JOIN barang b ON b.id=t.barang_id LEFT JOIN users u ON u.id=t.user_id WHERE $where ORDER BY t.tanggal DESC,t.id DESC");$s->execute($params);
 header('Content-Type:text/csv; charset=utf-8');header('Content-Disposition:attachment; filename="laporan_gudang_'.$from.'_'.$to.'.csv"');$out=fopen('php://output','w');fputcsv($out,['Tanggal','Kode','Nama Barang','Kategori','Satuan','Jenis','Jumlah','Referensi','Keterangan','Petugas']);while($r=$s->fetch()){fputcsv($out,$r);}fclose($out);exit;
}
$stmt=$pdo->prepare("SELECT t.*,b.kode_barang,b.nama_barang,b.satuan,u.name FROM transaksi t JOIN barang b ON b.id=t.barang_id LEFT JOIN users u ON u.id=t.user_id WHERE $where ORDER BY t.tanggal DESC,t.id DESC");$stmt->execute($params);$rows=$stmt->fetchAll();
$stok=$pdo->query("SELECT * FROM barang WHERE active=1 ORDER BY nama_barang")->fetchAll();
$totalMasuk=$totalKeluar=0;foreach($rows as $r){if($r['jenis']==='MASUK')$totalMasuk+=(int)$r['jumlah'];else$totalKeluar+=(int)$r['jumlah'];}
page_start('Laporan','laporan');
?>
<section class="panel no-print"><form class="filter" method="get"><label>Dari<input type="date" name="from" value="<?=e($from)?>"></label><label>Sampai<input type="date" name="to" value="<?=e($to)?>"></label><label>Jenis<select name="jenis"><option value="SEMUA" <?=$jenis==='SEMUA'?'selected':''?>>Semua</option><option value="MASUK" <?=$jenis==='MASUK'?'selected':''?>>Masuk</option><option value="KELUAR" <?=$jenis==='KELUAR'?'selected':''?>>Keluar</option></select></label><button class="btn primary">Tampilkan</button><button type="button" onclick="window.print()" class="btn">🖨 Cetak / Simpan PDF</button><a class="btn" href="?from=<?=e($from)?>&to=<?=e($to)?>&jenis=<?=e($jenis)?>&export=csv">↓ Ekspor CSV</a></form></section>
<section class="report-head"><div><h1>Laporan Gudang PLN ULP Tanjung Pura</h1><p>Periode <?=e(date('d-m-Y',strtotime($from)))?> s/d <?=e(date('d-m-Y',strtotime($to)))?> • <?=e($jenis==='SEMUA'?'Semua transaksi':$jenis)?></p></div><div class="report-meta">Dicetak: <?=e(date('d-m-Y H:i'))?></div></section>
<section class="cards report-cards"><div class="stat"><span>Total Transaksi</span><strong><?=count($rows)?></strong></div><div class="stat"><span>Total Masuk</span><strong><?=number_format($totalMasuk)?></strong></div><div class="stat"><span>Total Keluar</span><strong><?=number_format($totalKeluar)?></strong></div></section>
<section class="panel"><div class="panel-title"><h3>Riwayat Transaksi</h3><span><?=count($rows)?> transaksi</span></div><div class="table-wrap"><table><thead><tr><th>No</th><th>Tanggal</th><th>Kode</th><th>Barang</th><th>Jenis</th><th>Jumlah</th><th>Petugas</th><th>Keterangan</th></tr></thead><tbody><?php foreach($rows as $i=>$r): ?><tr><td><?=$i+1?></td><td><?=e(date('d-m-Y',strtotime($r['tanggal'])))?></td><td><?=e($r['kode_barang'])?></td><td><?=e($r['nama_barang'])?></td><td><span class="badge <?=$r['jenis']==='MASUK'?'green':'orange'?>"><?=e($r['jenis'])?></span></td><td><b><?=number_format((int)$r['jumlah'])?></b> <?=e($r['satuan'])?></td><td><?=e($r['name']??'-')?></td><td><?=e($r['keterangan']??'-')?></td></tr><?php endforeach; ?><?php if(!$rows): ?><tr><td colspan="8" class="empty">Tidak ada transaksi pada periode tersebut.</td></tr><?php endif; ?></tbody></table></div></section>
<section class="panel"><div class="panel-title"><h3>Posisi Stok Saat Ini</h3></div><div class="table-wrap"><table><thead><tr><th>Kode</th><th>Nama Barang</th><th>Kategori</th><th>Stok</th><th>Minimum</th><th>Lokasi</th></tr></thead><tbody><?php foreach($stok as $b): ?><tr><td><?=e($b['kode_barang'])?></td><td><?=e($b['nama_barang'])?></td><td><?=e($b['kategori'])?></td><td><b class="<?=$b['stok']<=$b['stok_minimum']?'danger-text':''?>"><?=number_format((int)$b['stok'])?></b> <?=e($b['satuan'])?></td><td><?=number_format((int)$b['stok_minimum'])?></td><td><?=e($b['lokasi'])?></td></tr><?php endforeach; ?></tbody></table></div></section>
<?php page_end(); ?>
